<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { api } from '../api'
import NumberSettingRow from './NumberSettingRow.vue'
import ToggleSettingRow from './ToggleSettingRow.vue'
interface Simple { temperature: number; max_tokens: number }
interface Settings { chat: { temperature: number; max_rounds: number; stage_budgets: { exploring: number; responding: number } }; solve: Simple & { max_rounds: number; max_replans: number }; research: Simple & { researching: { note_agent_mode: string; tool_timeout: number; tool_max_retries: number; paper_search_years_limit: number } }; question: Simple & { exploring: { max_iterations: number; tool_summarizer: { enabled: boolean; max_tokens: number } } }; co_writer: Simple; vision_solver: Simple; math_animator: Simple; visualize: Simple }
const props = withDefaults(defineProps<{ pending?: unknown; revision?: number }>(), { revision: 0 })
const emit = defineEmits<{ change: [value: Settings]; loaded: [value: Settings] }>()
const settings = reactive<Settings>({ chat: { temperature: 0.7, max_rounds: 12, stage_budgets: { exploring: 4000, responding: 4000 } }, solve: { temperature: 0.7, max_tokens: 4000, max_rounds: 12, max_replans: 2 }, research: { temperature: 0.7, max_tokens: 4000, researching: { note_agent_mode: 'auto', tool_timeout: 60, tool_max_retries: 2, paper_search_years_limit: 5 } }, question: { temperature: 0.7, max_tokens: 4000, exploring: { max_iterations: 6, tool_summarizer: { enabled: true, max_tokens: 1200 } } }, co_writer: { temperature: 0.7, max_tokens: 4000 }, vision_solver: { temperature: 0.7, max_tokens: 4000 }, math_animator: { temperature: 0.7, max_tokens: 4000 }, visualize: { temperature: 0.7, max_tokens: 4000 } })
const loading = ref(true); const error = ref('')
async function load() { loading.value = true; error.value = ''; try { const live = await api<Settings>('/api/capabilities/settings'); Object.assign(settings, (props.pending as Settings | undefined) ?? live); emit('loaded', live) } catch (cause) { error.value = cause instanceof Error ? cause.message : '能力设置加载失败' } finally { loading.value = false } }
onMounted(load); watch(() => props.revision, load)
function changed() { emit('change', JSON.parse(JSON.stringify(settings))) }
function patchChat<K extends keyof Settings['chat']>(key: K, value: Settings['chat'][K]) { settings.chat[key] = value; changed() }
function patchStage(stage: 'exploring' | 'responding', value: number) { settings.chat.stage_budgets[stage] = value; changed() }
function patchSimple(cap: 'solve' | 'co_writer' | 'vision_solver' | 'math_animator' | 'visualize' | 'research' | 'question', value: Partial<Simple>) { Object.assign(settings[cap], value); changed() }
function patchSolve(value: Partial<Settings['solve']>) { Object.assign(settings.solve, value); changed() }
function patchResearching(value: Partial<Settings['research']['researching']>) { Object.assign(settings.research.researching, value); changed() }
function patchExploring(value: Partial<Settings['question']['exploring']>) { Object.assign(settings.question.exploring, value); changed() }
function patchSummarizer(value: Partial<Settings['question']['exploring']['tool_summarizer']>) { Object.assign(settings.question.exploring.tool_summarizer, value); changed() }
</script>
<template><div><header class="legacy-settings-page-header"><h1>能力</h1><p>配置各能力的 LLM 参数与运行时选项。</p></header><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="legacy-settings-loading">加载中…</p><template v-else><section class="legacy-setting-section"><header><h2>Chat</h2><p>探索代理循环后进入回复阶段，各阶段分别限制每次 LLM 调用的 max_tokens。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" description="所有 Chat 阶段共用的采样温度。" :value="settings.chat.temperature" :min="0" :max="2" :step="0.05" float @change="patchChat('temperature', $event)" /><NumberSettingRow title="最大轮数" description="每轮对话中探索循环的 LLM 轮次上限；没有工具调用时提前结束。" :value="settings.chat.max_rounds" :min="1" :max="50" @change="patchChat('max_rounds', $event)" /><NumberSettingRow title="探索阶段（max tokens）" description="每个探索循环轮次的预算，包括笔记和工具调用。" :value="settings.chat.stage_budgets.exploring" :min="256" :max="200000" :step="100" @change="patchStage('exploring', $event)" /><NumberSettingRow title="回复阶段（max tokens）" description="最终面向用户回复的预算。" :value="settings.chat.stage_budgets.responding" :min="256" :max="200000" :step="100" @change="patchStage('responding', $event)" /></div></section><section class="legacy-setting-section"><header><h2>Solve</h2><p>深度解题以 plan / finish-step / replan 为主线的单代理循环。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.solve.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('solve', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.solve.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('solve', { max_tokens: $event })" /><NumberSettingRow title="最大轮数" description="一次解题轮次的全部 LLM 预算，包括规划、工具调用和收尾。" :value="settings.solve.max_rounds" :min="1" :max="50" @change="patchSolve({ max_rounds: $event })" /><NumberSettingRow title="最大 replan 次数" description="规划器在一次解题中可修订计划的次数。" :value="settings.solve.max_replans" :min="0" :max="10" @change="patchSolve({ max_replans: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Question</h2><p>深度题目生成流程。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.question.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('question', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.question.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('question', { max_tokens: $event })" /><NumberSettingRow title="探索最大迭代次数" description="规划前探索循环的迭代上限。" :value="settings.question.exploring.max_iterations" :min="1" :max="50" @change="patchExploring({ max_iterations: $event })" /><ToggleSettingRow title="启用工具结果摘要" description="总结较长的工具输出，减少提示词预算。" :checked="settings.question.exploring.tool_summarizer.enabled" @change="patchSummarizer({ enabled: $event })" /><NumberSettingRow title="工具摘要（max tokens）" :value="settings.question.exploring.tool_summarizer.max_tokens" :min="128" :max="200000" :step="100" @change="patchSummarizer({ max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Research</h2><p>深度研究流程；迭代次数由聊天输入中的深度选择器控制，不在此设置。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.research.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('research', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.research.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('research', { max_tokens: $event })" /><NumberSettingRow title="工具超时（秒）" description="研究阶段每个工具的墙钟超时。" :value="settings.research.researching.tool_timeout" :min="1" :max="600" @change="patchResearching({ tool_timeout: $event })" /><NumberSettingRow title="工具最大重试次数" :value="settings.research.researching.tool_max_retries" :min="0" :max="10" @change="patchResearching({ tool_max_retries: $event })" /><NumberSettingRow title="论文搜索年限" description="论文搜索向前扫描的年数。" :value="settings.research.researching.paper_search_years_limit" :min="1" :max="50" @change="patchResearching({ paper_search_years_limit: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Math animator</h2><p>Manim 动画与图片生成流程。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.math_animator.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('math_animator', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.math_animator.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('math_animator', { max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Visualize</h2><p>SVG、图表和示意图生成循环。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.visualize.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('visualize', { temperature: $event })" /><NumberSettingRow title="Max tokens" description="推理模型可能将大部分预算用于内部推理；画布为空时可适当提高。" :value="settings.visualize.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('visualize', { max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Co-writer</h2><p>选区编辑与内联改写代理。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.co_writer.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('co_writer', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.co_writer.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('co_writer', { max_tokens: $event })" /></div></section></template></div></template>
